 #[test]fn export_native_prefix_linear_and_dag(){
  let mut b=Builder::new();let acc=b.alloc_qubits(56);let e=b.alloc_qubits(3);let nm=b.alloc_qubits(3);let k1=b.alloc_qubit();let k2=b.alloc_qubit();let inputs:Vec<_>=acc[..6].iter().chain(&e).chain(&nm).copied().chain([k1,k2]).collect();ON.with(|x|x.set(true));fold_fwd_v2(&mut b,&acc,[e[0],e[1],e[2]],[nm[0],nm[1],nm[2]],k1,k2,0,None,false,0);ON.with(|x|x.set(false));let(add,_)=SNAP.with(|x|x.borrow_mut().take()).unwrap();assert_eq!(b.active_qubits(),95);let ops=b.take_ops();let mut q=vec![0u64;95];for(i,w)in inputs.iter().enumerate(){q[w.0 as usize]=1u64<<(1+i);}let mut gates=Vec::<[u64;3]>::new();
  for o in &ops{use OperationType::*;let t=o.q_target.0 as usize;let a=o.q_control1.0 as usize;let c=o.q_control2.0 as usize;match o.kind{X=>q[t]^=1,CX=>q[t]^=q[a],CCX=>{assert_eq!(q[t],0,"new helper must be clean at birth");let id=gates.len();gates.push([o.q_target.0,q[a],q[c]]);q[t]=1u64<<(15+id);},Register|AppendToRegister=>{},_=>panic!("nonlinear DAG export unexpected operation {:?}",o.kind)}}
  assert_eq!(gates.len(),31);let mask=|f:&Lin|f.w.iter().fold(u64::from(f.one),|v,w|v^q[w.0 as usize]);let fields:Vec<_>=(4..17).chain(std::iter::once(17)).chain(32..39).map(|i|mask(&add[i])).collect();let low=vec![q[acc[0].0 as usize]^q[e[0].0 as usize],q[acc[1].0 as usize]^q[e[1].0 as usize]^q[64],q[acc[2].0 as usize]^q[e[2].0 as usize]^q[65],q[acc[3].0 as usize]^q[66],q[acc[4].0 as usize]^q[67]^q[nm[0].0 as usize]^q[acc[0].0 as usize],q[acc[5].0 as usize]^q[74]^q[nm[1].0 as usize]^q[acc[1].0 as usize]^q[69]^q[nm[0].0 as usize]^q[acc[0].0 as usize]];
  let out=std::env::var("PREFIX_DAG_OUT").expect("metadata output path");std::fs::write(out,format!("{{\"input_qubits\":{:?},\"gates\":{:?},\"helper_masks\":{:?},\"field_masks\":{:?},\"low_sum_masks\":{:?},\"c6_mask\":{},\"operations\":{},\"scope\":\"Native prefix metadata only, not a circuit optimization or score\"}}\n",inputs.iter().map(|x|x.0).collect::<Vec<_>>(),gates,q[64..].to_vec(),fields,low,q[76],ops.len())).unwrap();
 }
